INSERT INTO nodes (id, type, name, data) VALUES ('hmab', 'org', 'Houston Music Advisory Board', '{"orgType":"city","description":"Mayoral-appointed City of Houston advisory board, founded Sept 15, 2022 by ordinance 2022-694 (Code of Ordinances Ch.2 Art.XI Div.6), drafted by Gracie Chávez. Members must live in Houston, be active in the music industry, and serve as volunteers. Fiscal sponsor: MOSE. 2026 focus: Music Business Development, Healthcare/Wellness, Funding/Grants.","website":"https://www.houston-music.live"}');
INSERT INTO nodes (id, type, name, data) VALUES ('moca', 'org', 'Mayor''s Office of Cultural Affairs (MOCA)', '{"orgType":"city","description":"Housed the Music & Cultural Tourism Officer role (Gracie Chávez, 2022-2025). Office dissolved ~2025; restoring it — and Houston''s Music Friendly Texas certification with it — is the board''s central advocacy thread since May 2025.","website":"https://www.houstontx.gov/culturalaffairs"}');
INSERT INTO nodes (id, type, name, data) VALUES ('mose', 'org', 'Mayor''s Office of Special Events (MOSE)', '{"orgType":"city","description":"HMAB''s fiscal sponsor — processes board funds and travel reimbursements. Also the city''s event-permitting office."}');
INSERT INTO nodes (id, type, name, data) VALUES ('coh-boards', 'org', 'City of Houston Boards & Commissions', '{"orgType":"city","description":"The application system every sitting HMAB member must stay current in; froze new board nominations until compliance (Apr 2026).","website":"https://www.houstontx.gov/boards/apply.html"}');
INSERT INTO nodes (id, type, name, data) VALUES ('arts-culture-committee', 'org', 'Houston City Council Arts + Culture Committee', '{"orgType":"city","description":"Monthly council committee (began May 2024) where HMAB fights its civic battles — MOCA restoration, Music Officer rehire."}');
