INSERT INTO nodes (id, type, name, data) VALUES ('gracie-chavez', 'person', 'Gracie Chávez', '{"aka":["La Mera Mera","DJ Gracie Chavez"],"boardStatus":"founder","boardRole":"Founder / Secretary (2025)","roles":["Founder, Houston Music Advisory Board (drafted the 2022 city ordinance)","Founding Music & Cultural Tourism Officer, Mayor''s Office of Cultural Affairs (2022 – Jan 2025)","Co-Founder / Creative Director, Bombón Music Texas","Programs Director, Fresh Arts; Make Music Day Houston lead","DJ (Third Root Music); Houston Press Best DJ 2016"],"notes":"The network hub — four hats interlink city, nonprofit, and music scenes. Bombón selected to rework the official 2026 FIFA World Cup Houston theme song. Applying to the Recording Academy (Music Exec) Feb 2026. Worked with Frost as far back as ExxonMobil (2014).","links":["https://www.bombontexas.com","https://graciechavez.carrd.co/"]}');
INSERT INTO nodes (id, type, name, data) VALUES ('jason-woods', 'person', 'Jason Woods', '{"aka":["Flash Gordon Parks","Flash"],"boardStatus":"officer","boardRole":"Chair","roles":["HMAB Board Chair (2nd term through Jan 2027)","Ethnomusicologist; DJ","Exhibiting artist, THIS WAY: A Houston Group Show at CAMH (Dec 2023)","Led 2023 preservation focus (El Dorado Ballroom, SugarHill Records documentation)"],"notes":"First met Frost at his Moody Center talk, Oct 2017.","links":["https://www.flashgordonparks.com","https://mixcloud.com/flashgparks"]}');
INSERT INTO nodes (id, type, name, data) VALUES ('marissa-saenz', 'person', 'Marissa Saenz', '{"boardStatus":"officer","boardRole":"Vice-Chair","roles":["HMAB Vice-Chair (2nd term through Jan 2027; joined Dec 2023)","Owner, Rukaz Kultura — her Lawndale office is the board’s standing meeting venue","Runs board admin: applications, nominee votes, meeting logistics"],"links":["https://www.rukaz.work"]}');
INSERT INTO nodes (id, type, name, data) VALUES ('dria-thornton', 'person', 'Dria Thornton', '{"aka":["Dria","Diondria Thornton"],"boardStatus":"officer","boardRole":"Treasurer","roles":["HMAB Treasurer (joined Dec 2023)","16x RIAA Platinum, Grammy- and Dove-nominated composer/vocalist (SESAC / Timpoo Publishing)","2024 Let Creativity Happen grant awardee","Books talent for East River; proposed Beats on the Bayou townhall"],"notes":"Client list spans City of Houston MOCA, Serena Williams / Serena Ventures, Lincoln, Peerspace, 5 Alarm Music, Warner Chappell Production Music, Audio Network, Hobby Center, Color Creative/Raedio, Wyn Beauty. Music on Netflix \"From Scratch\". Moderating a music panel at Houston Media Conference (2026)."}');
INSERT INTO nodes (id, type, name, data) VALUES ('tracy-dejarnett', 'person', 'Tracy DeJarnett', '{"boardStatus":"officer","boardRole":"Secretary (elected 1/24/2024)","roles":["HMAB Secretary; term expired Jan 2025, stayed active","CMO & Co-Founder, HoustonLive; founder/producer of Houston Bluesfest","Founder, The Brandsoup Agency; Co-Founder, Launch Music Lab (publishing + artist development)","2024 TCMA Texas Country Music Industry Professional of the Year finalist"],"links":["https://linktr.ee/TracyDeJarnett","https://houstonbluesfest.com"]}');
