INSERT INTO nodes (id, type, name, data) VALUES ('hmab-meeting-2024-01', 'event', 'First 2024 Board Meeting (new members seated)', '{"date":"2024-01-24","category":"board-meeting","description":"Dria, Frost, and Marissa welcomed (onboarded Dec 2023). Tracy elected Secretary, Dria Treasurer. 2024 priorities: fundraising, collaboration, music business development, music tourism, busking/permitting. 2023 recap: 422 listening-session respondents."}');
