INSERT INTO nodes (id, type, name, data) VALUES ('houston-music-conference-2023', 'event', 'Houston Music Conference 2023', '{"date":"2023-10","category":"conference","description":"Welcome at Saint Arnold, closing at the Continental Club (Flash, Ichikara Valdez, The Mexican Blackbird DJ sets; Ruben Moreno, DJ Candlestick, Shame on Me, Blossom Aloe). Frost built the materials — Music Board + TMO + MOCA logos on every piece."}');
